			}
		}
	}

	return resp, err
}

// logEnabledLogger returns the logger to use for structured logging, or nil if
// logging is disabled either by feature flag or because the configured logger
// is not enabled at the debug level.
func (t *otelAttributeTransport) logEnabledLogger(ctx context.Context) *slog.Logger {
	if !gax.IsFeatureEnabled("LOGGING") {
		return nil
	}
	if t.logger == nil || !t.logger.Enabled(ctx, slog.LevelDebug) {
		return nil
	}
	return t.logger
}

