	t.Helper()
	s := strings.TrimSpace(buf.String())
	if s == "" {
		return nil
	}
	if strings.Count(s, "\n") > 0 {
		t.Fatalf("expected exactly one record, got:\n%s", s)
	}
	var m map[string]any
	if err := json.Unmarshal([]byte(s), &m); err != nil {
		t.Fatalf("bad json: %v\n%s", err, s)
